package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReferenceType#getGenericSignature
 */
public class ReferenceType_getGenericSignature_TriageGen0Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        // Since ReferenceType constructor is protected, we use the static construct method.
        // We need to mock the behavior of the referenced type.
        JavaType mockReferencedType = Mockito.mock(JavaType.class);

        // The method calls sb.append('<'), then _referencedType.getGenericSignature(sb), then sb.append(">;")
        // We simulate the behavior of the referenced type's getGenericSignature
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("MockType");
            return sb;
        });

        // Construct the ReferenceType with the mocked referenced type
        // ReferenceType.construct(Class<?> cls, JavaType refType, Object valueHandler, Object typeHandler)
        ReferenceType referenceType = ReferenceType.construct(
                String.class, 
                mockReferencedType, 
                null, 
                null
        );

        StringBuilder sb = new StringBuilder("Prefix");

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected sequence: 
        // 1. "Prefix" (initial)
        // 2. append('<') -> "Prefix<"
        // 3. mockReferencedType.getGenericSignature -> "Prefix<MockType"
        // 4. append(">;") -> "Prefix<MockType>;"
        String expected = "Prefix<MockType>;";
        Assert.assertEquals("The generic signature should be correctly formatted", expected, result.toString());

        // Verify identity (the method returns the same StringBuilder instance)
        Assert.assertSame("The method should return the same StringBuilder instance passed in", sb, result);
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Arrange
        JavaType mockReferencedType = Mockito.mock(JavaType.class);
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("T");
            return sb;
        });

        ReferenceType referenceType = ReferenceType.construct(
                Object.class, 
                mockReferencedType, 
                null, 
                null
        );

        StringBuilder sb = new StringBuilder();

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        Assert.assertEquals("<T>;", result.toString());
    }
}
